package postgres

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"testing"

	"github.com/KarakoramDev/Karakoram/internal/agentapi"
	"github.com/KarakoramDev/Karakoram/internal/engine/enginetest"
	"github.com/KarakoramDev/Karakoram/internal/infra"
)

// Fixtures were generated by the real pre-pgvector-bundle engine at 1cb6bd98,
// using the v0.4.5 artifact payloads (plus compatibility lookup aliases and the
// mongosh entry required by that engine's initialization). pgvector is still
// installed through its genuine 0.8.6 APT pin, not the current preparation path.
func TestCPUpgradePreservesPreparedMembers(t *testing.T) {
	for _, version := range []string{"16.15.1", "17.11.1", "18.6.1"} {
		t.Run(version, func(t *testing.T) {
			t.Setenv("KARAKORAM_ARTIFACT_MIRROR", "https://artifacts.example.invalid")
			p, rc, backend := setup(t, "single")
			fixture := enginetest.RestorePreparedCPUpgrade(t, rc, fmt.Sprintf("testdata/cp-upgrade-%s.json", version))
			legacyPrepare := strings.Join(fixture.Runtime.Prepare, "\n")
			if !strings.Contains(legacyPrepare, "pgvector='1:0.8.6-1.noble'") || strings.Contains(legacyPrepare, "0.8.7") {
				t.Fatal("fixture was not prepared by the legacy APT-based engine")
			}
			backend.services = enginetest.PreparedServices(fixture)
			backend.deployed = map[string]bool{}
			for name := range fixture.Configs {
				backend.deployed[name] = true
			}
			backend.actions = nil
			for range 3 {
				p = New(p.options)
				if _, err := p.Sync(t.Context(), rc); err != nil {
					t.Fatal(err)
				}
			}
			state, err := load(rc.Cluster)
			if err != nil {
				t.Fatal(err)
			}
			if state.Rolling != nil || state.Pending != nil || state.ExtensionsPending {
				t.Fatal("CP-only upgrade scheduled a package/config rollout")
			}
			for name, before := range fixture.Configs {
				after, err := p.MemberConfig(t.Context(), rc, name)
				if err != nil {
					t.Fatal(err)
				}
				enginetest.RequirePreparedConfig(t, name, before.EngineSpec, after.EngineSpec)
			}
			for _, action := range backend.actions {
				if strings.HasPrefix(action, "deploy:") || strings.HasPrefix(action, "update-extensions:") {
					t.Fatalf("CP-only upgrade changed installed extensions: %s", action)
				}
			}

			backend.genericOverrides = map[string]agentapi.Status{}
			wrapped := &cpUpgradeRolloutBackend{
				rolloutBackend: &rolloutBackend{fakeBackend: backend, rc: rc},
				prepares:       map[string][]string{},
			}
			rc.Backend = wrapped
			op := rolloutOperation(true)
			done := false
			for range 80 {
				p = New(p.options)
				result, err := p.RunOperation(t.Context(), rc, op)
				if err != nil {
					t.Fatal(err)
				}
				if result.Checkpoint != nil {
					op.Checkpoint = result.Checkpoint
				}
				if result.Done {
					done = true
					break
				}
			}
			if !done {
				t.Fatal("prepared profile rollout did not complete")
			}
			prepare := strings.Join(wrapped.prepares["demop0"], "\n")
			if !strings.Contains(prepare, "pgvector-pg"+strings.Split(version, ".")[0]+"-0.8.7") || strings.Contains(prepare, "pgvector='") {
				t.Fatal("rollout did not prepare the source-built pgvector bundle")
			}
			if !slices.Contains(backend.actions, "update-extensions:demop0:vector") {
				t.Fatal("rollout omitted extension UPDATE", backend.actions)
			}
		})
	}
}

type cpUpgradeRolloutBackend struct {
	*rolloutBackend
	prepares map[string][]string
}

func (b *cpUpgradeRolloutBackend) Deploy(ctx context.Context, name string, deployment infra.Deployment) (infra.Op, error) {
	b.prepares[name] = slices.Clone(deployment.Runtime.Prepare)
	return b.rolloutBackend.Deploy(ctx, name, deployment)
}
